-- Synthetic fixture only. No real rows, HTTP or email. Entire scenario rolls back.
begin;
set local statement_timeout='12s';
set local lock_timeout='2s';
do $$ declare c uuid:=gen_random_uuid(); u uuid; sys uuid; kind text; pid uuid:=gen_random_uuid(); begin
